import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, color, positionLocal, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, DirectionalLight, AmbientLight, Color, Box3, Vector3, DoubleSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10', surface: '#14141a', ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 0.55, hex: '#101017' }, { at: 1, hex: '#16161d' }]
  };
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#16161d' }];

  const root = new Group();
  const tweens = [];
  const primHandles = [];

  // ---- Backdrop plane (engineered vertical gradient) ----
  const cLow = color(stops[0].hex);
  const cMid = color(stops[Math.min(1, stops.length - 1)].hex ?? stops[stops.length - 1].hex);
  const cHigh = color(stops[stops.length - 1].hex);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    const lowMid = mix(cLow, cMid, smoothstep(0.0, 0.55, v));
    const grad = mix(lowMid, cHigh, smoothstep(0.55, 1.0, v));
    bgMat.colorNode = grad;
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---- Plinth ----
  const plinthMat = new MeshStandardNodeMaterial();
  plinthMat.color = new Color(colors.surface);
  plinthMat.roughness = 0.7;
  plinthMat.metalness = 0.3;
  const plinth = new Mesh(new CylinderGeometry(1.4, 1.45, 0.25, 64), plinthMat);
  plinth.position.set(0, -1.225, 0); // top face ~ y = -1.1
  root.add(plinth);

  // ---- Contact shadow ----
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.55);
    shadowMat.colorNode = vec4(vec3(0.0), a);
    shadowMat.depthWrite = false;
  }
  const shadow = new Mesh(new PlaneGeometry(3.2, 3.2), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.34, 0);
  root.add(shadow);

  // ---- Lighting (node-local rim + accent) ----
  const ambient = new AmbientLight(0xffffff, 0.35);
  root.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.15);
  key.position.set(2.4, 3.0, 3.2);
  root.add(key);

  const rim = new DirectionalLight(new Color(colors.accent), 1.4);
  rim.position.set(-3.2, 1.0, -1.0); // grazes left case flank
  root.add(rim);

  const back = new DirectionalLight(0xffffff, 0.6);
  back.position.set(-1.0, 2.0, -3.0);
  root.add(back);

  // ---- Watch mesh group (orbit/hover target) ----
  const watchGroup = new Group();
  watchGroup.position.set(0, 0, 0);
  root.add(watchGroup);

  const meshUrl = config.meshUrl ?? config.intent?.visualSpec?.meshUrl ?? '/prism-mock/orrery/meshes/watch.glb';
  if (meshUrl && ctx.glbLoader) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      const scene = gltf.scene ?? gltf;
      if (!scene) return;

      // Normalize to 2.2 units tall, top on plinth top (y=-1.1)
      const box = new Box3().setFromObject(scene);
      const size = new Vector3(); box.getSize(size);
      const center = new Vector3(); box.getCenter(center);
      const scale = size.y > 0 ? 2.2 / size.y : 1;
      scene.scale.setScalar(scale);
      scene.position.set(
        -center.x * scale,
        -center.y * scale, // center at origin of watchGroup
        -center.z * scale
      );

      // Elevate so base rests on plinth top: place watchGroup base at y=-1.1
      const scaledHalf = (size.y * scale) / 2;
      scene.position.y += scaledHalf; // base at 0
      watchGroup.position.y = -1.1;

      // Brushed-metal PBR override
      scene.traverse((o) => {
        if (o.isMesh) {
          const m = new MeshPhysicalNodeMaterial();
          m.color = new Color(colors.paper).multiplyScalar(0.75);
          m.roughness = 0.52;
          m.metalness = 0.55;
          m.clearcoat = 0.2;
          m.clearcoatRoughness = 0.4;
          if ('anisotropy' in m) m.anisotropy = 0.8;
          o.material = m;
        }
      });

      watchGroup.add(scene);

      // entrance: rise-in + weighted settle
      scene.scale.setScalar(scale * 0.96);
      tweens.push(gsap.fromTo(watchGroup.position, { y: -0.7 }, { y: -1.1, duration: 0.7, ease: 'power3.out' }));
      tweens.push(gsap.fromTo(scene.scale, { x: scale * 0.96, y: scale * 0.96, z: scale * 0.96 },
        { x: scale, y: scale, z: scale, duration: 0.9, ease: 'power4.out', delay: 0.1 }));
    }).catch(() => {});
  }

  // ---- Text ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  root.add(textGroup);

  const roleY = { headline: -1.5, body: -1.85, caption: -2.15 };
  for (const item of items) {
    const role = item.role ?? 'body';
    const txt = String(item.text ?? '');
    let fontSize = 26, col = colors.paper, ls = 0;
    if (role === 'headline') { fontSize = 68; col = colors.paper; }
    else if (role === 'caption') { fontSize = 18; col = colors.accent; ls = 0.08 * fontSize; }
    else { fontSize = 26; col = colors.paper; }

    const t = ctx.fontAtlas.createText(txt, {
      fontSize, color: col, align: 'center', letterSpacingPx: ls
    });
    t.position.set(0, roleY[role] ?? -1.85, 0.1);
    textGroup.add(t);
    tweens.push(gsap.fromTo(t.position, { y: (roleY[role] ?? -1.85) + 0.2 },
      { y: roleY[role] ?? -1.85, duration: 0.5, ease: 'power2.out', delay: 0.3 }));
  }

  // ---- Primitives ----
  const prims = config.cinematicPrimitives ?? [];
  for (const p of prims) {
    const fn = ctx.primitives?.[p.name];
    if (!fn) continue;
    const target = (p.name === 'orbit' || p.name === 'depth-rotate') ? watchGroup : root;
    try {
      const h = fn(target, p.params ?? {});
      if (h) primHandles.push(h);
    } catch (e) {}
  }

  // ---- Hover handlers (fallback tilt if depth-rotate primitive absent) ----
  const handlers = {
    onPointerMove: (e) => {
      const nx = (e?.uv?.x ?? 0.5) - 0.5;
      const ny = (e?.uv?.y ?? 0.5) - 0.5;
      const max = 6 * Math.PI / 180;
      gsap.to(watchGroup.rotation, { x: -ny * max, z: nx * max, duration: 0.3, ease: 'power2.out' });
    },
    onPointerLeave: () => {
      gsap.to(watchGroup.rotation, { x: 0, z: 0, duration: 0.9, ease: 'power4.out' });
    }
  };
  root.userData.handlers = handlers;

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    tweens.forEach((t) => t && t.kill && t.kill());
    primHandles.forEach((h) => h && h.cleanup && h.cleanup());
    root.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose?.();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose?.());
        else o.material?.dispose?.();
      }
    });
  };

  return root;
}
